detaileddescription.para:
Usage example: sf::Timet1=sf::seconds(0.1f);
std::int32_tmilli=t1.asMilliseconds();//100

sf::Timet2=sf::milliseconds(30);
std::int64_tmicro=t2.asMicroseconds();//30'000

sf::Timet3=sf::microseconds(-800'000);
floatsec=t3.asSeconds();//-0.8

sf::Timet4=std::chrono::milliseconds(250);
std::chrono::microsecondsmicro2=t4.toDuration();//250'000us
